// Visible Session Value Terrain Model
// Volume-profile value engine: POC + Value Area from session distribution.

profRows = input(24, "Profile Rows", 10, 48, 1)
vaPct = input(70, "Value Area %", 50, 90, 5)
sessLen = input(150, "Visible Bars", 50, 500, 10)
extendLines = input(true, "Extend POC/VAH/VAL Until Break")
show3D = input(true, "Show 3D Terrain")
show2D = input(true, "Show 2D Profile When 3D Off")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Session range from visible set ──────────────────────────────
sessHigh = highest(high, sessLen)
sessLow = lowest(low, sessLen)
sessRange = sessHigh - sessLow
if sessRange <= 0 {
    sessRange := close * 0.01
}
rowH = sessRange / profRows

// ─── Row volumes: distribute each bar's volume by overlap ────────
// Recomputed every bar over the session window using overlap weighting.
var rowA = array()
if array.size(rowA) == 0 {
    k = 0
    while k < 48 {
        array.push(rowA, 0.0)
        k := k + 1
    }
}
r = 0
while r < profRows {
    array.set(rowA, r, 0.0)
    r := r + 1
}
totalVol = 0.0
b = 0
while b < sessLen {
    bh = high[b]
    bl = low[b]
    bv = volume[b]
    totalVol := totalVol + bv
    bhSpan = bh - bl
    if bhSpan <= 0 {
        bhSpan := sessRange * 0.001
    }
    rr = 0
    while rr < profRows {
        rLow = sessLow + rr * rowH
        rHigh = rLow + rowH
        ovTop = bh
        if rHigh < ovTop {
            ovTop := rHigh
        }
        ovBot = bl
        if rLow > ovBot {
            ovBot := rLow
        }
        ov = ovTop - ovBot
        if ov > 0 {
            share = ov / bhSpan
            array.set(rowA, rr, array.get(rowA, rr) + bv * share)
        }
        rr := rr + 1
    }
    b := b + 1
}

// ─── POC: row with maximum volume ────────────────────────────────
pocRow = 0
pocVol = array.get(rowA, 0)
q = 1
while q < profRows {
    qv = array.get(rowA, q)
    if qv > pocVol {
        pocVol := qv
        pocRow := q
    }
    q := q + 1
}
pocPrice = sessLow + (pocRow + 0.5) * rowH
avgRowVol = totalVol / profRows

// ─── Value Area: sort rows by volume desc, accumulate to vaPct ───
var ordA = array()
if array.size(ordA) == 0 {
    k2 = 0
    while k2 < 48 {
        array.push(ordA, 0.0)
        k2 := k2 + 1
    }
}
o = 0
while o < profRows {
    array.set(ordA, o, o)
    o := o + 1
}
a = 0
while a < profRows {
    c = 0
    while c < profRows - 1 - a {
        ca = array.get(ordA, c)
        cb = array.get(ordA, c + 1)
        va = array.get(rowA, ca)
        vb = array.get(rowA, cb)
        if vb > va {
            array.set(ordA, c, cb)
            array.set(ordA, c + 1, ca)
        }
        c := c + 1
    }
    a := a + 1
}
targetVol = totalVol * vaPct / 100
accumVol = 0.0
vaTopRow = pocRow
vaBotRow = pocRow
s = 0
while s < profRows {
    ri = array.get(ordA, s)
    rv = array.get(rowA, ri)
    accumVol := accumVol + rv
    if ri > vaTopRow {
        vaTopRow := ri
    }
    if ri < vaBotRow {
        vaBotRow := ri
    }
    if accumVol >= targetVol {
        s := profRows
    }
    s := s + 1
}
vahPrice = sessLow + (vaTopRow + 1) * rowH
valPrice = sessLow + vaBotRow * rowH
vaWidth = vahPrice - valPrice

// ─── Value status ────────────────────────────────────────────────
insideVal = close >= valPrice and close <= vahPrice
aboveVal = close > vahPrice
belowVal = close < valPrice
prevInside = close[1] >= valPrice[1] and close[1] <= vahPrice[1]
prevOutside = not prevInside
volConfirm = volume > avgRowVol

// ─── Signals ─────────────────────────────────────────────────────
buySig = prevInside and close > vahPrice and volConfirm
sellSig = prevInside and close < valPrice and volConfirm
returnSig = prevOutside and insideVal
coneSize = (volume / (avgRowVol + 0.0000001) - 0.5) * markerSize
if coneSize < 0.6 {
    coneSize := 0.6
}
if coneSize > 2.2 {
    coneSize := 2.2
}

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
    plotshape_3d(bar_index, high, "Breakout", "coneup", "#22cc88", coneSize, 1, "separate")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
    plotshape_3d(bar_index, low, "Breakdown", "conedown", "#ff4477", coneSize, 1, "separate")
}
if returnSig {
    plotshape(bar_index, close, "Back To Value", "circle", "#ffd43b")
}

